cat > src/order.js <<'EOF'
// An order is a list of lines; amounts are in cents.
// An order may carry an optional order-level discount, `discountCents` (defaults to 0).
function subtotal(order) { return order.lines.reduce((s, l) => s + l.unitCents * l.qty, 0); }
function discount(order) {
  const d = order.discountCents ?? 0;
  if (!Number.isInteger(d) || d < 0) throw new Error('discountCents must be a non-negative integer');
  if (d > subtotal(order)) throw new Error('discount cannot exceed the order subtotal');
  return d;
}
// Subtotal after the discount; this is the amount VAT is charged on.
function discountedSubtotal(order) { return subtotal(order) - discount(order); }
module.exports = { subtotal, discount, discountedSubtotal };
EOF
cat > src/tax.js <<'EOF'
const { discountedSubtotal } = require('./order');
const RATE = 0.2; // VAT, charged on the order subtotal after any discount
function tax(order) { return Math.round(discountedSubtotal(order) * RATE); }
module.exports = { tax, RATE };
EOF
cat > src/invoice.js <<'EOF'
const { subtotal, discount } = require('./order');
const { tax } = require('./tax');
// Invoices are legal documents: each line shown here must reconcile with the totals.
function invoice(order) {
  const sub = subtotal(order); const d = discount(order); const t = tax(order);
  return { lines: order.lines, subtotalCents: sub, discountCents: d, taxCents: t, totalCents: sub - d + t };
}
module.exports = { invoice };
EOF
cat > src/refund.js <<'EOF'
const { RATE } = require('./tax');
const { subtotal, discount } = require('./order');
// Refund one order line: the line's price, less its share of any order discount,
// plus the VAT charged on that discounted amount.
function refundLine(order, lineIndex, qty) {
  const line = order.lines[lineIndex];
  if (qty > line.qty) throw new Error('cannot refund more than was bought');
  const gross = line.unitCents * qty;
  const sub = subtotal(order);
  const share = sub === 0 ? 0 : Math.round(discount(order) * gross / sub); // pro rata by value
  const net = gross - share;
  return net + Math.round(net * RATE);
}
module.exports = { refundLine };
EOF
cat >> test/shop.test.js <<'EOF'
const discounted = { ...order, discountCents: 500 };
test('discount reduces taxable amount and invoice reconciles', () => {
  const i = invoice(discounted);
  assert.strictEqual(i.discountCents, 500); assert.strictEqual(i.taxCents, 400);
  assert.strictEqual(i.totalCents, i.subtotalCents - i.discountCents + i.taxCents); assert.strictEqual(i.totalCents, 2400);
});
test('no discount behaves as before', () => assert.strictEqual(invoice(order).discountCents, 0));
test('refund deducts the line\'s pro-rata share of the discount', () => assert.strictEqual(refundLine(discounted, 0, 1), 1000));
test('refunding everything returns what was paid', () => {
  const total = refundLine(discounted, 0, 2) + refundLine(discounted, 1, 1);
  assert.strictEqual(total, invoice(discounted).totalCents);
});
test('invalid discounts are rejected', () => {
  assert.throws(() => invoice({ ...order, discountCents: -1 }));
  assert.throws(() => invoice({ ...order, discountCents: 2501 }));
});
EOF
